(*----- Function f32_sub -----*)

Definition f32_sub_return_wit_1 := 
(
forall (b_pre: fp32) (a_pre: fp32) ,
  TT && emp 
|--
  “ (fp32_bits_equal (fp32_sub (a_pre) (b_pre)) (fp32_sub (a_pre) (b_pre)) ) ”
  &&  emp
) \/
(
forall (b_pre: fp32) (a_pre: fp32) ,
  TT && emp 
|--
  “ (fp32_bits_equal (fp32_sub (a_pre) (b_pre)) (fp32_sub (a_pre) (b_pre)) ) ”
  &&  emp
).

Definition f32_sub_return_wit_1_split_goal_1 := 
forall (b_pre: fp32) (a_pre: fp32) ,
  (fp32_bits_equal (fp32_sub (a_pre) (b_pre)) (fp32_sub (a_pre) (b_pre)) )
.

(*----- Function qcp_rvv_sub_lane32 -----*)

Definition qcp_rvv_sub_lane32_return_wit_1 := 
(
forall (vl_pre: Z) (i_pre: Z) (b_pre: fp32) (a_pre: fp32) (PreH1 : (i_pre >= vl_pre)) (PreH2 : (0 <= i_pre)) (PreH3 : (i_pre < 32)) (PreH4 : (0 <= vl_pre)) (PreH5 : (vl_pre <= 32)) ,
  TT && emp 
|--
  “ (fp32_bits_equal (fp32_of_real (0.0)) (vadd_active_sub (i_pre) (vl_pre) (a_pre) (b_pre)) ) ”
  &&  emp
) \/
(
forall (vl_pre: Z) (i_pre: Z) (b_pre: fp32) (a_pre: fp32) (PreH1 : (i_pre >= vl_pre)) (PreH2 : (0 <= i_pre)) (PreH3 : (i_pre < 32)) (PreH4 : (0 <= vl_pre)) (PreH5 : (vl_pre <= 32)) ,
  TT && emp 
|--
  “ (fp32_bits_equal (fp32_of_real (0.0)) (vadd_active_sub (i_pre) (vl_pre) (a_pre) (b_pre)) ) ”
  &&  emp
).

Definition qcp_rvv_sub_lane32_return_wit_1_split_goal_1 := 
forall (vl_pre: Z) (i_pre: Z) (b_pre: fp32) (a_pre: fp32) (PreH1 : (i_pre >= vl_pre)) (PreH2 : (0 <= i_pre)) (PreH3 : (i_pre < 32)) (PreH4 : (0 <= vl_pre)) (PreH5 : (vl_pre <= 32)) ,
